module adder_16bit (
    input [15:0] a, 
    input [15:0] b, 
    input Cin, 
    output [15:0] y, 
    output Co
);
// Internal wires for the outputs of the two 8-bit adders
wire [7:0] sum1, sum2;
wire c1, c2;
// Instantiate two 8-bit adders
assign {c1, sum1} = a[7:0] + b[7:0] + Cin;
assign {c2, sum2} = a[15:8] + b[15:8] + c1;
// Concatenate the results to form the 16-bit output
assign y = {sum2, sum1};
// Assign the final carry-out
assign Co = c2;
endmodule
